package com.aegisdispatch.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="audit_logs") public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String actor,action,entityType; @Column(name="entity_id") private UUID entityId; @Column(name="previous_state") private String previousState; @Column(name="new_state") private String newState; private String metadata; @Column(name="created_at") private Instant createdAt;
 public Long getId(){return id;} public String getActor(){return actor;} public void setActor(String v){actor=v;} public String getAction(){return action;} public void setAction(String v){action=v;} public String getEntityType(){return entityType;} public void setEntityType(String v){entityType=v;} public UUID getEntityId(){return entityId;} public void setEntityId(UUID v){entityId=v;} public String getPreviousState(){return previousState;} public void setPreviousState(String v){previousState=v;} public String getNewState(){return newState;} public void setNewState(String v){newState=v;} public String getMetadata(){return metadata;} public void setMetadata(String v){metadata=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;}}
